//! Cargo-driven `mbedtls.dll` link, generated by tools/cargo_cell_gen.py
//! from the cmake link it replaces.
//! The module is C, compiled and linked by reactos-link: there is no Rust body.

use reactos_link::{Linker, ModuleKind, MsvcrtexKind};
use std::env;

fn main() {
    let arch = env::var("CARGO_CFG_TARGET_ARCH").expect("CARGO_CFG_TARGET_ARCH");
    let (target_json, entry, image_base) = match arch.as_str() {
        "x86" => ("i686-pc-windows-gnu", "_DllMainCRTStartup@12", Some(0x72690000u64)),
        "x86_64" => ("x86_64-pc-windows-gnu", "DllMainCRTStartup", Some(0x7fef0000000u64)),
        "aarch64" => ("aarch64-pc-windows-gnullvm", "DllMainCRTStartup", Some(0x7fef0000000u64)),
        o => panic!("mbedtls-cargo: unsupported arch {o}"),
    };

    let link_order: &[&str] = match arch.as_str() {
        "x86" => &["import:advapi32", "import:msvcrt", "import:kernel32", "import:ntdll", "body", "engine:oldnames"],
        "x86_64" => &["import:advapi32", "import:msvcrt", "import:kernel32", "import:ntdll", "body", "engine:oldnames"],
        "aarch64" => &["import:advapi32", "import:msvcrt", "import:kernel32", "import:ntdll", "body", "engine:oldnames"],
        _ => unreachable!(),
    };

    // The module's part of cmake's windres command; reactos-link adds what every
    // module shares from reactos-link/cflags/rc.<arch>.flags (Linker::rc).
    let rc_includes: &[&str] = &[
        "@build/dll/3rdparty/mbedtls",
        "vendor/mbedtls",
        "@std",
        "sdk/lib/pseh/include",
        "vendor/opengl-headers/include",
        "vendor/libdxg/include",
        "vendor/mbedtls/include",
    ];
    let rc_flags: &[&str] = &[];
    let rc_defines: &[&str] = &[
        "CRTDLL",
        "MINGW_HAS_SECURE_API",
        "WINVER=0x502",
        "_CRT_DECLARE_NONSTDC_NAMES=1",
        "_CRT_NONSTDC_NO_DEPRECATE",
        "_DLL",
        "_WIN32_WINNT=0x502",
        "__USE_CRTIMP",
    ];

    Linker::new(target_json)
        .c_from_compile_db("mbedtls_shims", &["sdk/lib/mbedtls_reactos/strsafe_wrapper.c", "sdk/lib/mbedtls_reactos/entropy_hardware_poll.c", "vendor/mbedtls/aes.c", "vendor/mbedtls/aesce.c", "vendor/mbedtls/aesni.c", "vendor/mbedtls/aria.c", "vendor/mbedtls/asn1parse.c", "vendor/mbedtls/asn1write.c", "vendor/mbedtls/base64.c", "vendor/mbedtls/bignum.c", "vendor/mbedtls/bignum_core.c", "vendor/mbedtls/bignum_mod.c", "vendor/mbedtls/bignum_mod_raw.c", "vendor/mbedtls/block_cipher.c", "vendor/mbedtls/camellia.c", "vendor/mbedtls/ccm.c", "vendor/mbedtls/chacha20.c", "vendor/mbedtls/chachapoly.c", "vendor/mbedtls/cipher.c", "vendor/mbedtls/cipher_wrap.c", "vendor/mbedtls/cmac.c", "vendor/mbedtls/constant_time.c", "vendor/mbedtls/ctr_drbg.c", "vendor/mbedtls/debug.c", "vendor/mbedtls/des.c", "vendor/mbedtls/dhm.c", "vendor/mbedtls/dsa.c", "vendor/mbedtls/ecdh.c", "vendor/mbedtls/ecdsa.c", "vendor/mbedtls/ecjpake.c", "vendor/mbedtls/ecp.c", "vendor/mbedtls/ecp_curves.c", "vendor/mbedtls/ecp_curves_new.c", "vendor/mbedtls/entropy.c", "vendor/mbedtls/entropy_poll.c", "vendor/mbedtls/error.c", "vendor/mbedtls/gcm.c", "vendor/mbedtls/hkdf.c", "vendor/mbedtls/hmac_drbg.c", "vendor/mbedtls/lmots.c", "vendor/mbedtls/lms.c", "vendor/mbedtls/md.c", "vendor/mbedtls/md5.c", "vendor/mbedtls/memory_buffer_alloc.c", "vendor/mbedtls/mps_reader.c", "vendor/mbedtls/mps_trace.c", "vendor/mbedtls/net_sockets.c", "vendor/mbedtls/nist_kw.c", "vendor/mbedtls/oid.c", "vendor/mbedtls/padlock.c", "vendor/mbedtls/pem.c", "vendor/mbedtls/pk.c", "vendor/mbedtls/pk_ecc.c", "vendor/mbedtls/pk_wrap.c", "vendor/mbedtls/pkcs12.c", "vendor/mbedtls/pkcs5.c", "vendor/mbedtls/pkcs7.c", "vendor/mbedtls/pkparse.c", "vendor/mbedtls/pkwrite.c", "vendor/mbedtls/platform.c", "vendor/mbedtls/platform_util.c", "vendor/mbedtls/poly1305.c", "vendor/mbedtls/psa_crypto.c", "vendor/mbedtls/psa_crypto_aead.c", "vendor/mbedtls/psa_crypto_cipher.c", "vendor/mbedtls/psa_crypto_client.c", "vendor/mbedtls/psa_crypto_driver_wrappers_no_static.c", "vendor/mbedtls/psa_crypto_ecp.c", "vendor/mbedtls/psa_crypto_ffdh.c", "vendor/mbedtls/psa_crypto_hash.c", "vendor/mbedtls/psa_crypto_mac.c", "vendor/mbedtls/psa_crypto_pake.c", "vendor/mbedtls/psa_crypto_random.c", "vendor/mbedtls/psa_crypto_rsa.c", "vendor/mbedtls/psa_crypto_se.c", "vendor/mbedtls/psa_crypto_slot_management.c", "vendor/mbedtls/psa_crypto_storage.c", "vendor/mbedtls/psa_its_file.c", "vendor/mbedtls/psa_util.c", "vendor/mbedtls/ripemd160.c", "vendor/mbedtls/rsa.c", "vendor/mbedtls/rsa_alt_helpers.c", "vendor/mbedtls/sha1.c", "vendor/mbedtls/sha256.c", "vendor/mbedtls/sha3.c", "vendor/mbedtls/sha512.c", "vendor/mbedtls/ssl_cache.c", "vendor/mbedtls/ssl_ciphersuites.c", "vendor/mbedtls/ssl_client.c", "vendor/mbedtls/ssl_cookie.c", "vendor/mbedtls/ssl_debug_helpers_generated.c", "vendor/mbedtls/ssl_msg.c", "vendor/mbedtls/ssl_ticket.c", "vendor/mbedtls/ssl_tls.c", "vendor/mbedtls/ssl_tls12_client.c", "vendor/mbedtls/ssl_tls12_server.c", "vendor/mbedtls/ssl_tls13_client.c", "vendor/mbedtls/ssl_tls13_generic.c", "vendor/mbedtls/ssl_tls13_keys.c", "vendor/mbedtls/ssl_tls13_server.c", "vendor/mbedtls/threading.c", "vendor/mbedtls/timing.c", "vendor/mbedtls/version.c", "vendor/mbedtls/version_features.c", "vendor/mbedtls/x509.c", "vendor/mbedtls/x509_create.c", "vendor/mbedtls/x509_crl.c", "vendor/mbedtls/x509_crt.c", "vendor/mbedtls/x509_csr.c", "vendor/mbedtls/x509write.c", "vendor/mbedtls/x509write_crt.c", "vendor/mbedtls/x509write_csr.c"])
        .whole_c_objects("mbedtls_shims")
        .rc("vendor/mbedtls/mbedtls.rc", rc_includes, rc_flags, rc_defines)
        .spec2def("vendor/mbedtls/mbedtls.spec", "mbedtls.dll")
        .import_lib("dll/win32/advapi32/advapi32.spec", "advapi32.dll", "advapi32")
        .import_lib("dll/win32/msvcrt/msvcrt.spec", "msvcrt.dll", "msvcrt")
        .import_lib("dll/win32/kernel32/kernel32.spec", "kernel32.dll", "kernel32")
        .import_lib("dll/ntdll/def/ntdll.spec", "ntdll.dll", "ntdll")
        // The body, import libs and static libs in cmake's link order: the first
        // to define a symbol wins. cmake-built ones are reused until each has a
        // cargo home; `engine:` ones reactos-link builds.
        .link_order(link_order)
        .msvcrtex_crt(MsvcrtexKind::Dll)
        // No code of its own: link nothing from rustc's bin (its panic
        // handler, i386's rsbegin/rsend), so the PE is cmake's.
        .shell_less()
        .link(ModuleKind::Win32Dll {
            entry: entry.into(),
            image_base,
            subsystem: None,
        });
}
